<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,shallowRef,watch} from 'vue';
import {ArrowLeft,ArrowRight,Check,CheckCircle2,FileArchive,FolderArchive,GitBranch,LoaderCircle,RefreshCw,Upload,X} from 'lucide-vue-next';
import type {BranchItem,RepoSummary} from '@oxen/shared';
import type {ZipImportInspection,ZipImportMapping,ZipImportPlan,ZipImportResult} from '../../../../packages/shared/src/releases';
import {post,remove,repoBase,request} from '../api';
import {useAppStore} from '../stores/app';
const props=defineProps<{repos?:RepoSummary[];initialNamespace?:string;initialRepo?:string;initialBranch?:string}>();
const emit=defineEmits<{close:[];back:[];imported:[value:ZipImportResult]}>();
const app=useAppStore(),dialog=ref<HTMLElement>(),file=shallowRef<File>(),inspection=ref<ZipImportInspection>(),plan=ref<ZipImportPlan>(),error=ref(''),busy=ref(false),validating=ref(false),committing=ref(false);
const mode=ref<ZipImportMapping['mode']>('tables'),paths=ref<string[]>([]),idField=ref(''),attachmentFields=ref<string[]>([]),repositories=ref<RepoSummary[]>(props.repos??[]),createNew=ref(!props.initialRepo&&app.status?.identity?.kind==='owner'),namespace=ref(props.initialNamespace??'local'),repo=ref(''),selectedRepo=ref(props.initialRepo?`${props.initialNamespace??'local'}/${props.initialRepo}`:''),branch=ref(props.initialBranch??'main'),description=ref(''),branches=ref<BranchItem[]>([]),targetLoading=ref(false),confirm=ref(false);
const owner=computed(()=>app.status?.identity?.kind==='owner');
const modes=computed(()=>[...new Set(inspection.value?.candidates.map(item=>item.mode)??[])]);
const options=computed(()=>[...new Set(inspection.value?.candidates.filter(item=>item.mode===mode.value).flatMap(item=>item.paths)??[])]);
const columns=computed(()=>[...new Set(inspection.value?.candidates.filter(item=>item.mode===mode.value).flatMap(item=>item.columns??[])??[])]);
const target=computed(()=>repositories.value.find(item=>`${item.namespace}/${item.name}`===selectedRepo.value));
const expectedCommit=computed(()=>branches.value.find(item=>item.name===branch.value)?.commitId);
const canCommit=computed(()=>!!inspection.value&&!!plan.value&&confirm.value&&!busy.value&&!validating.value&&!committing.value&&!targetLoading.value&&(createNew.value?owner.value&&!!namespace.value.trim()&&!!repo.value.trim():!!target.value&&!!expectedCommit.value));
let generation=0,planGeneration=0,targetGeneration=0,disposed=false;let previousFocus:HTMLElement|null=null;
const modeName=(value:string)=>({release:'标准发布/工作快照包',tables:'JSONL / CSV / TSV 表格',directories:'每个 Skill 目录一个样本',archives:'每个 ZIP 附件一个样本'}[value]??value);
const mapping=():ZipImportMapping=>({mode:mode.value,paths:[...paths.value],...(idField.value&&mode.value==='tables'?{idField:idField.value}:{}),...(mode.value==='tables'?{attachmentFields:[...attachmentFields.value]}:{})});
function chooseMode(){plan.value=undefined;confirm.value=false;idField.value='';attachmentFields.value=[];paths.value=mode.value==='tables'?options.value.slice(0,1):[...options.value];}
async function chooseFile(value?:File){if(!value||committing.value)return;const current=++generation,previous=inspection.value?.id;++planGeneration;validating.value=false;file.value=value;inspection.value=undefined;plan.value=undefined;error.value='';confirm.value=false;busy.value=true;try{if(previous)await remove('/import/zip/'+previous).catch(()=>{});if(!/\.zip$/i.test(value.name))throw new Error('请选择 .zip 文件。');if(value.size>64*1024*1024)throw new Error('网页 ZIP 导入上限为 64 MiB。');const body=new FormData();body.append('file',value,value.name);const result=await request<ZipImportInspection>('/import/zip',{method:'POST',body});if(disposed||current!==generation)return;inspection.value=result;mode.value=result.candidates.some(item=>item.mode==='release')?'release':result.candidates[0]?.mode??'tables';chooseMode();if(!repo.value)repo.value=value.name.replace(/\.zip$/i,'').toLowerCase().replace(/[^a-z0-9._-]+/g,'-').replace(/^[^a-z0-9]+|[-.]+$/g,'').slice(0,90)||'imported-dataset';}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)busy.value=false;}}
function inputFile(event:Event){const element=event.target as HTMLInputElement;void chooseFile(element.files?.[0]);element.value='';}
async function validate(){if(!inspection.value||!paths.value.length||validating.value)return;validating.value=true;plan.value=undefined;confirm.value=false;error.value='';const current=++planGeneration;try{const result=await post<ZipImportPlan>('/import/zip/'+inspection.value.id+'/plan',mapping());if(current===planGeneration&&!disposed)plan.value=result;}catch(cause){if(current===planGeneration)error.value=(cause as Error).message;}finally{if(current===planGeneration)validating.value=false;}}
async function loadTarget(){const current=++targetGeneration;branches.value=[];if(!target.value||createNew.value)return;targetLoading.value=true;try{const value=await request<BranchItem[]>(repoBase(target.value.namespace,target.value.name)+'/branches');if(current!==targetGeneration)return;branches.value=value;if(!value.some(item=>item.name===branch.value))branch.value=target.value.defaultBranch||value[0]?.name||'main';}catch(cause){if(current===targetGeneration)error.value=(cause as Error).message;}finally{if(current===targetGeneration)targetLoading.value=false;}}
async function refreshRepositories(){try{repositories.value=await request('/repos');if(!createNew.value)await loadTarget();}catch(cause){error.value=(cause as Error).message;}}
async function commit(){if(!canCommit.value||!plan.value||!inspection.value)return;committing.value=true;error.value='';try{const value=await post<ZipImportResult>('/import/zip/'+inspection.value.id+'/commit',{mapping:mapping(),fingerprint:plan.value.fingerprint,namespace:createNew.value?namespace.value.trim():target.value!.namespace,repo:createNew.value?repo.value.trim():target.value!.name,branch:branch.value.trim(),createRepository:createNew.value,...(!createNew.value?{expectedCommit:expectedCommit.value}:{}),description:description.value});emit('imported',value);}catch(cause){error.value=(cause as Error).message;}finally{committing.value=false;}}
function close(back=false){if(committing.value)return;if(back)emit('back');else emit('close');}
function trap(event:KeyboardEvent){if(event.key!=='Tab')return;const list=dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)');if(!list?.length)return;if(event.shiftKey&&document.activeElement===list[0]){event.preventDefault();list[list.length-1]!.focus();}else if(!event.shiftKey&&document.activeElement===list[list.length-1]){event.preventDefault();list[0]!.focus();}}
watch(()=>[mode.value,paths.value.join('\n'),idField.value,attachmentFields.value.join('\n')],()=>{++planGeneration;validating.value=false;plan.value=undefined;confirm.value=false;});watch(selectedRepo,loadTarget);watch(createNew,()=>{if(!createNew.value)void loadTarget();});
onMounted(async()=>{previousFocus=document.activeElement as HTMLElement;await nextTick();dialog.value?.querySelector<HTMLInputElement>('input[type=file]')?.focus();try{if(!repositories.value.length)repositories.value=await request('/repos');if(!selectedRepo.value)selectedRepo.value=repositories.value[0]?`${repositories.value[0].namespace}/${repositories.value[0].name}`:'';else void loadTarget();}catch(cause){error.value=(cause as Error).message;}});
onBeforeUnmount(()=>{if(inspection.value)void remove('/import/zip/'+inspection.value.id).catch(()=>{});disposed=true;++generation;++planGeneration;++targetGeneration;previousFocus?.focus();});
</script>
<template><div class="modal-backdrop zip-import-backdrop" @click.self="close()" @keydown.esc.stop.prevent="close()"><section ref="dialog" class="zip-import-dialog" role="dialog" aria-modal="true" aria-labelledby="zip-import-title" @keydown="trap"><header><div><span class="zip-eyebrow"><FolderArchive :size="15"/>数据集导入</span><h2 id="zip-import-title">导入 ZIP 数据包</h2><p>识别入口、确认映射、校验后提交。所有内容仅作为数据，不安装或执行 Skill。</p></div><button class="icon-button" :disabled="committing" aria-label="关闭 ZIP 导入" @click="close()"><X :size="19"/></button></header><div class="zip-import-content"><button class="zip-back" :disabled="committing" @click="close(true)"><ArrowLeft :size="13"/>返回 JSONL 导入</button><ol class="zip-steps"><li :class="{done:inspection}"><i>1</i>识别数据包</li><li :class="{done:plan}"><i>2</i>映射与校验</li><li :class="{done:committing}"><i>3</i>确认并提交</li></ol><label class="zip-drop" @dragover.prevent @drop.prevent="chooseFile($event.dataTransfer?.files[0])"><FileArchive :size="29"/><strong>{{file?.name??'选择或拖入 ZIP 文件'}}</strong><span>支持 JSONL/CSV/TSV、Skill 目录、逐样本 ZIP 与本项目标准发布包 · 最大 64 MiB</span><input type="file" accept=".zip,application/zip" :disabled="committing||busy" aria-label="选择 ZIP 数据包" @change="inputFile"/></label><p v-if="busy" class="zip-working" role="status"><LoaderCircle class="spin" :size="17"/>正在安全读取清单与校验内容…</p>
<template v-if="inspection"><div class="zip-inspection"><CheckCircle2 :size="18"/><div><strong>{{inspection.entryCount}} 个文件 · 展开 {{(inspection.totalUncompressedSize/1024/1024).toFixed(2)}} MiB</strong><code>SHA-256 {{inspection.sha256}}</code><span>预览有效至 {{new Date(inspection.expiresAt).toLocaleTimeString()}}</span></div></div><div v-if="inspection.warnings.length" class="zip-warnings"><p v-for="warning in inspection.warnings" :key="warning">{{warning}}</p></div><section class="zip-mapping"><header><h3>选择数据入口与身份规则</h3><span>多候选不会自动合并</span></header><label class="field">导入模式<select v-model="mode" :disabled="committing" @change="chooseMode"><option v-for="item in modes" :key="item" :value="item">{{modeName(item)}}</option></select></label><div class="zip-path-heading"><strong>选中 {{paths.length}} / {{options.length}} 个入口</strong><button class="btn btn-ghost" :disabled="committing" @click="paths=paths.length===options.length?[]:[...options]">{{paths.length===options.length?'取消全选':'全选'}}</button></div><div class="zip-paths"><label v-for="item in options" :key="item"><input v-model="paths" type="checkbox" :value="item" :disabled="committing"/><span>{{item||'根目录 Skill'}}</span></label></div><label v-if="mode==='tables'" class="field">稳定身份字段（可选）<select v-model="idField" :disabled="committing"><option value="">生成独立稳定身份，保留原字段</option><option v-for="column in columns" :key="column" :value="column">{{column}}</option></select></label><p class="zip-help">原始 ZIP 按 SHA-256 留存。选中的原始字段和嵌套类型保留，标签独立保存；嵌套 ZIP 不递归执行或打开。</p><button class="btn" :disabled="!paths.length||validating||committing" @click="validate"><LoaderCircle v-if="validating" class="spin" :size="15"/><CheckCircle2 v-else :size="15"/>校验此映射</button></section>
<fieldset v-if="mode==='tables'&amp;&amp;columns.length" class="zip-attachment-fields"><legend>附件路径字段（可选）</legend><p>仅勾选指向包内文件的字段；URL 不会作为附件抓取。</p><label v-for="column in columns" :key="column"><input v-model="attachmentFields" type="checkbox" :value="column" :disabled="committing"/>{{column}}</label></fieldset><section v-if="plan" class="zip-plan"><header><CheckCircle2 :size="18"/><h3>映射校验通过</h3></header><div class="zip-plan-stats"><span><strong>{{plan.rowCount.toLocaleString()}}</strong>样本</span><span><strong>{{plan.columns.length}}</strong>原始字段</span><span><strong>{{plan.attachmentCount}}</strong>Skill 附件</span></div><p v-for="warning in plan.warnings" :key="warning" class="zip-help">{{warning}}</p><p class="zip-help">原包及导入映射随同一次提交保留。导入的既有审核证据仅作来源，不作为本机审核通过。</p></section>
<section class="zip-target"><header><h3>导入目标</h3><span>已有受管理数据集不会被覆盖</span></header><button class="btn btn-ghost zip-refresh-repos" :disabled="committing||targetLoading" @click="refreshRepositories"><RefreshCw :size="13"/>刷新项目列表</button><div class="zip-target-options"><label><input v-model="createNew" type="radio" :value="true" :disabled="!owner||committing"/>新建项目</label><label><input v-model="createNew" type="radio" :value="false" :disabled="committing"/>已有空项目</label></div><div v-if="createNew" class="zip-target-grid"><label class="field">命名空间<input v-model="namespace" required pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" :disabled="committing"/></label><label class="field">项目名称<input v-model="repo" required pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" :disabled="committing"/></label></div><label v-else class="field">项目<select v-model="selectedRepo" :disabled="committing"><option value="">选择有数据编辑权限的空项目</option><option v-for="item in repositories" :key="item.namespace+'/'+item.name" :value="item.namespace+'/'+item.name">{{item.namespace}} / {{item.name}}</option></select></label><label class="field">目标分支<input v-if="createNew" v-model="branch" :disabled="committing"/><select v-else v-model="branch" :disabled="committing||targetLoading"><option v-for="item in branches" :key="item.name" :value="item.name">{{item.name}}</option></select></label><p v-if="expectedCommit&&!createNew" class="zip-commit"><GitBranch :size="12"/>预期提交 {{expectedCommit.slice(0,12)}} · 分支变化将拒绝覆盖</p><label v-if="createNew" class="field">项目描述（可选）<textarea v-model="description" rows="2" maxlength="4000" :disabled="committing"/></label><label v-if="plan" class="zip-confirm"><input v-model="confirm" type="checkbox" :disabled="committing"/><span>确认将 {{plan.rowCount.toLocaleString()}} 条样本和上述附件作为数据导入，并在目标分支生成一次提交。</span></label></section></template><div v-if="error" class="error-state" role="alert">{{error}}</div></div><footer><button class="btn" :disabled="committing" @click="close()">取消</button><button class="btn btn-primary" :disabled="!canCommit" @click="commit"><LoaderCircle v-if="committing" class="spin" :size="15"/><Upload v-else :size="15"/>{{committing?'正在导入并提交…':'导入、提交并打开'}}</button></footer></section></div></template>
<style scoped>
.zip-refresh-repos{font-size:11px;min-height:29px;margin:-8px 0 16px;padding-left:0}
.zip-attachment-fields{display:flex;gap:12px;flex-wrap:wrap;min-width:0;margin:20px 0;padding:14px;border:1px solid var(--line);border-radius:5px}.zip-attachment-fields legend{font-size:12px;padding:0 5px}.zip-attachment-fields p{width:100%;font-size:11px;color:var(--muted);line-height:1.8}.zip-attachment-fields label{display:flex;align-items:center;gap:7px;font-size:11px;overflow-wrap:anywhere}
.zip-import-backdrop{z-index:120}.zip-import-dialog{width:820px;max-width:100%;max-height:calc(100vh - 48px);overflow:auto;background:var(--surface);border:1px solid var(--line);border-radius:10px;box-shadow:0 25px 100px #0008;color:var(--text)}.zip-import-dialog>header{display:flex;align-items:start;justify-content:space-between;gap:20px;padding:24px 27px;border-bottom:1px solid var(--line);position:sticky;top:0;background:var(--surface);z-index:2}.zip-eyebrow{display:flex;gap:8px;align-items:center;color:var(--primary-hover);font-size:11px;margin-bottom:9px}.zip-import-dialog h2{font-size:23px;font-weight:500}.zip-import-dialog>header p{font-size:12px;color:var(--muted);line-height:1.8;margin-top:8px;max-width:620px}.zip-import-content{padding:20px 27px 26px}.zip-back{display:flex;align-items:center;gap:7px;font-size:11px;color:var(--muted);margin-bottom:18px}.zip-steps{list-style:none;padding:0;margin:0 0 22px;display:flex;justify-content:space-between;gap:12px}.zip-steps li{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--muted)}.zip-steps i{width:23px;height:23px;display:grid;place-items:center;border:1px solid var(--line);border-radius:50%;font-size:10px;font-style:normal}.zip-steps .done{color:var(--primary-hover)}.zip-steps .done i{border-color:var(--primary)}.zip-drop{border:1px dashed var(--line);border-radius:7px;background:var(--bg);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;padding:27px 22px;text-align:center;cursor:pointer}.zip-drop:hover{border-color:var(--primary)}.zip-drop>svg{color:var(--primary-hover)}.zip-drop strong{font-size:14px;overflow-wrap:anywhere}.zip-drop span{font-size:11px;color:var(--muted);line-height:1.8}.zip-drop input{font-size:11px;max-width:100%;color:var(--muted);margin-top:5px}.zip-drop input::file-selector-button{border:1px solid var(--line);border-radius:4px;background:var(--surface-raised);color:var(--text);padding:7px 12px;margin-right:10px}.zip-working{display:flex;gap:9px;align-items:center;font-size:12px;color:var(--muted);margin:18px 0}.zip-inspection{display:flex;gap:11px;padding:16px;border:1px solid var(--line);border-radius:6px;background:var(--surface-raised);margin-top:17px}.zip-inspection>svg{color:var(--success);flex-shrink:0;margin-top:2px}.zip-inspection strong{display:block;font-size:13px;font-weight:500}.zip-inspection code{display:block;font-size:10px;color:var(--muted);overflow-wrap:anywhere;line-height:1.8;margin-top:8px}.zip-inspection span{font-size:10px;color:var(--muted);display:block;margin-top:6px}.zip-warnings{padding:12px 15px;background:var(--bg);border:1px solid var(--line);border-radius:5px;font-size:11px;color:var(--muted);line-height:1.8;margin-top:12px;max-height:150px;overflow:auto}.zip-warnings p{margin:4px 0;overflow-wrap:anywhere}.zip-mapping,.zip-target{margin-top:23px;padding-top:23px;border-top:1px solid var(--line)}.zip-mapping>header,.zip-target>header{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:19px}.zip-mapping h3,.zip-target h3{font-size:14px;font-weight:500}.zip-mapping>header span,.zip-target>header span{font-size:10px;color:var(--muted)}.zip-import-dialog .field{font-size:12px;margin-bottom:18px}.zip-import-dialog .field input,.zip-import-dialog .field select,.zip-import-dialog .field textarea{font-size:13px}.zip-path-heading{display:flex;justify-content:space-between;align-items:center;font-size:11px;margin:10px 0}.zip-path-heading strong{font-weight:500;color:var(--muted)}.zip-path-heading .btn{font-size:10px;min-height:28px}.zip-paths{max-height:200px;overflow:auto;border:1px solid var(--line);border-radius:5px;background:var(--bg);padding:5px;margin-bottom:18px}.zip-paths label{display:flex;align-items:start;gap:9px;padding:9px 10px;font-size:12px;line-height:1.7}.zip-paths label:hover{background:var(--surface-raised)}.zip-paths span{overflow-wrap:anywhere}.zip-paths input{margin-top:3px;flex-shrink:0}.zip-help{font-size:11px;color:var(--muted);line-height:1.9;margin:12px 0 17px}.zip-plan{border:1px solid color-mix(in srgb,var(--success) 35%,var(--line));background:color-mix(in srgb,var(--success) 4%,var(--surface));border-radius:6px;padding:17px;margin-top:20px}.zip-plan>header{display:flex;align-items:center;gap:9px;color:var(--success);font-size:13px}.zip-plan h3{font-size:13px;font-weight:500}.zip-plan-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:18px 0}.zip-plan-stats>span{font-size:10px;color:var(--muted)}.zip-plan-stats strong{display:block;font-size:23px;color:var(--text);font-weight:500;margin-bottom:6px}.zip-plan .zip-help:last-child{margin-bottom:0}.zip-target-options{display:flex;gap:22px;flex-wrap:wrap;margin-bottom:21px;font-size:12px}.zip-target-options label{display:flex;align-items:center;gap:8px}.zip-target-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.zip-commit{display:flex;align-items:center;gap:7px;font-size:10px;color:var(--muted);margin:-4px 0 20px}.zip-confirm{display:flex;align-items:start;gap:10px;border:1px solid var(--line);background:var(--surface-raised);padding:14px;border-radius:5px;font-size:12px;line-height:1.8}.zip-confirm input{margin-top:4px;flex-shrink:0}.zip-import-dialog>footer{display:flex;justify-content:end;gap:10px;padding:18px 27px;border-top:1px solid var(--line);position:sticky;bottom:0;background:var(--surface);z-index:2}.zip-import-content>.error-state{margin-top:20px}@media(max-width:600px){.zip-import-dialog{max-height:calc(100vh - 24px)}.zip-import-dialog>header{padding:20px}.zip-import-dialog h2{font-size:20px}.zip-import-content{padding:18px 20px 22px}.zip-steps{gap:7px}.zip-steps li{font-size:10px;gap:5px}.zip-steps i{width:19px;height:19px}.zip-drop{padding:23px 15px}.zip-mapping>header,.zip-target>header{align-items:start;flex-direction:column;gap:6px}.zip-target-grid{grid-template-columns:1fr;gap:0}.zip-plan-stats{gap:12px}.zip-plan-stats strong{font-size:21px}.zip-import-dialog>footer{padding:16px 20px}.zip-import-dialog>footer .btn{font-size:12px}}
</style>
